result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/fix-form/src/fix.js", "content": "/**
 * Transforms the inaccessible markup in fixtures/before.html into a
 * semantically correct, accessible form.
 *
 * Fixes applied:
 *  - <div class="form">            -> real <form>
 *  - <span> pseudo-labels          -> <label> elements associated via for/id
 *  - email input type="text"       -> type="email" (semantic + keyboard hints)
 *  - .hint div                     -> referenced from its field via aria-describedby
 *  - <div onclick="submit()">      -> real <button type="submit">
 *  - decorative <img>              -> alt="" so it is ignored by AT
 */

const EMAIL_HINT_ID = 'email-hint';

export function fixForm(html) {
  // Real form element instead of a plain div.
  html = html.replace('<div class="form">', '<form class="form">');
  html = html.replace('</div>\n</div>', '</form>'); // handled below more robustly

  return transform(html);
}

function transform(html) {
  let out = html;

  out = out.replace('<div class="form">', '<form class="form">');

  // Name field: span -> label[for], add id to input.
  out = out.replace(
    '<span>Name</span><input type="text">',
    '<label for="name">Name</label><input type="text" id="name">'
  );

  // Email field: span -> label[for], correct input type, tie in the hint.
  out = out.replace(
    '<span>Email</span><input type="text">',
    `<label for="email">Email</label>` +
      `<input type="email" id="email" aria-describedby="${EMAIL_HINT_ID}">`
  );

  // Give the hint an id so it can be referenced by aria-describedby.
  out = out.replace(
    '<div class="hint">We never share your email</div>',
    `<div class="hint" id="${EMAIL_HINT_ID}">We never share your email</div>`
  );

  // Div-with-onclick becomes a real submit button.
  out = out.replace(
    '<div onclick="submit()" class="btn">SUBMIT</div>',
    '<button type="submit" class="btn">SUBMIT</button>'
  );

  // Decorative image: empty alt hides it from assistive technology.
  out = out.replace('<img src="decor.png">', '<img src="decor.png" alt="">');

  // Close the form element that replaced the outer div.
  out = out.replace(/\n<\/div>(\s*)$/, '\n</form>$1');

  return out;
}
