result = await mcp.call_tool("tools", "ox-bridge-write", {"path": "/workspace/fix-form/test/fix.test.js", "content": "import { describe, it, expect } from 'vitest';
import { readFileSync } from 'node:fs';
import { join } from 'node:path';
import { JSDOM } from 'jsdom';
import axe from 'axe-core';
import { parse } from 'node-html-parser';
import { fixForm } from '../src/fix.js';

const beforeHtml = readFileSync(join(__dirname, '..', 'fixtures', 'before.html'), 'utf8');
const fixedHtml = fixForm(beforeHtml);

/** Run axe-core inside jsdom and return the results. */
async function runAxe(html) {
  const dom = new JSDOM(html);
  const { window } = dom;

  // Inject axe-core into the page and run it there.
  const script = window.document.createElement('script');
  script.textContent = axe.source;
  window.document.head.appendChild(script);

  return await new Promise((resolve, reject) => {
    // color-contrast is disabled: jsdom does no layout/painting, so contrast
    // (and any other rule needing real rendering) cannot be computed.
    window.axe.run(window.document, { rules: { 'color-contrast': { enabled: false } } })
      .then(resolve)
      .catch(reject);
  });
}

describe('form accessibility', () => {
  it('documents the BEFORE state: axe finds violations, including missing labels', async () => {
    const results = await runAxe(beforeHtml);
    const ids = results.violations.map((v) => v.id);

    expect(ids.length).toBeGreaterThan(0);
    expect(ids).toContain('label'); // inputs have no associated <label>
    expect(ids).toContain('button-name'); // div "button" has no accessible name
  });

  it('AFTER the fix: axe reports zero violations', async () => {
    const results = await runAxe(fixedHtml);
    expect(results.violations).toEqual([]);
  });

  it('has structurally correct label/for pairing', () => {
    const root = parse(fixedHtml);

    for (const [labelFor, inputId] of [['name', 'name'], ['email', 'email']]) {
      const label = root.querySelector(`label[for="${labelFor}"]`);
      expect(label).toBeTruthy();

      const input = root.querySelector(`input#${inputId}`);
      expect(input).toBeTruthy();
      // label's `for` points at an existing input id
      expect(input.getAttribute('id')).toBe(label.getAttribute('for'));
    }

    expect(root.querySelector('input#email').getAttribute('type')).toBe('email');
  });

  it('uses a real submit button instead of a clickable div', () => {
    const root = parse(fixedHtml);
    const button = root.querySelector('button[type="submit"]');
    expect(button).toBeTruthy();
    expect(button.text.trim()).toBe('SUBMIT');
    // The onclick div is gone
    expect(root.querySelector('.btn[onclick]')).toBeNull();
  });
});
"})
